import './App.css';

function OrgName() {
  return (
    <input type="text" id="orgname" placeholder="Enter Organization Name"></input>
  );
}

function AdminName() {
  return (
    <input type="text" id="adminname" placeholder="Enter Administrator Name"></input>
  );
}

export default function MyApp() {
  return (
    <div>
      <div class="OrgNameGroup">
        <text id="orgnametext"> Organization Name </text>
        <OrgName />
      </div>
      <div class="AdminNameGroup">
        <text id="adminnametext"> Admin </text>
        <AdminName />
      </div>
    </div>

  );
}
